CPC_QUESTIONS.push({"id":"fcc-cpc-290370","sourceQuestionId":"290370","t":"cpc-m11","moduleId":"cpc-m11","q":"O revel NÃO tem o direito de","o":["recorrer da sentença.","intervir no processo.","requerer a produção de provas.","constituir advogado.","apresentar contestação."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2015 • TEC 290370","source":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2015","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/290370","year":2015,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-291968","sourceQuestionId":"291968","t":"cpc-m11","moduleId":"cpc-m11","q":"Ocorrendo revelia,","o":["a presunção de veracidade dos fatos afirmados pelo autor não admite prova contrária.","seus efeitos, em nenhuma hipótese, podem ser excluídos, dada sua gravidade.","verificando o juiz um direito indisponível, ainda que o réu não conteste, o autor tem de fazer a prova dos fatos constitutivos de seu direito, defeso ao juiz o julgamento antecipado da lide.","embora haja a presunção de veracidade dos fatos alegados pelo autor, o réu revel tem o direito de ser intimado dos atos processuais subsequentes, tenha ou não advogado constituído nos autos.","seus efeitos só ocorrem em relação aos réus citados por edital ou por hora certa."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJRR/TJ RR/2015 • TEC 291968","source":"FCC - JE TJRR/TJ RR/2015","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/291968","year":2015,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-326360","sourceQuestionId":"326360","t":"cpc-m11","moduleId":"cpc-m11","q":"Se o réu, citado pessoalmente, não contestar a ação, consequentemente","o":["o juiz deverá julgar antecipadamente a lide, sempre, uma vez que a presunção de veracidade decorrente da revelia impede dilações probatórias.","os fatos afirmados pelo autor são reputados verdadeiros, efeito jurídico que não admite exceções, embora essa veracidade fática represente presunção relativa e não absoluta.","os fatos afirmados pelo autor são reputados verdadeiros de modo absoluto, não admitindo prova contrária em nenhuma hipótese, mas os efeitos jurídicos da revelia comportam exceções.","os fatos afirmados pelo autor são reputados verdadeiros, mas esse efeito jurídico admite exceções; além disso, essa veracidade fática representa presunção relativa e não absoluta.","os fatos afirmados pelo autor são tidos por presumivelmente verdadeiros, efeito jurídico que admite a única exceção de o litígio versar sobre direitos indisponíveis."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2015 • TEC 326360","source":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2015","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/326360","year":2015,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-326398","sourceQuestionId":"326398","t":"cpc-m11","moduleId":"cpc-m11","q":"Se o réu não contestar o pedido, reputar-se-ão verdadeiros, de maneira","o":["absoluta, os fatos afirmados pelo autor, salvo, dentre outras hipóteses, se o litígio versar sobre direitos indisponíveis.","absoluta, os fatos afirmados pelo autor, inclusive se o litígio versar sobre direitos indisponíveis.","absoluta, os fatos afirmados pelo autor, salvo, dentre outras hipóteses, se a petição inicial não estiver acompanhada de instrumento público que a lei considere indispensável à prova do ato.","relativa, os fatos afirmados pelo autor, salvo, dentre outras hipóteses, se o litígio versar sobre direitos indisponíveis.","relativa, os fatos afirmados pelo autor, inclusive se o litígio versar sobre direitos indisponíveis."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT9/TRT 9/Administrativa/\"Sem Especialidade\"/2015 • TEC 326398","source":"FCC - TJ TRT9/TRT 9/Administrativa/\"Sem Especialidade\"/2015","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/326398","year":2015,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-789028","sourceQuestionId":"789028","t":"cpc-m11","moduleId":"cpc-m11","q":"Na audiência de instrução e julgamento,","o":["uma vez instalada, o juiz tentará conciliar as partes, salvo se anteriormente tenha havido o emprego de outros métodos de solução consensual de conflitos, como a mediação e a arbitragem.","as provas orais serão produzidas em ordem peremptória, após o depoimento pessoal das partes.","sua unicidade e intermitência obsta que seja adiada, salvo apenas a hipótese de convenção das partes, em que será possível o adiamento por uma única vez.","enquanto depuserem o perito, os assistentes técnicos, as partes e as testemunhas, não poderão os advogados e o Ministério Público intervir ou apartear, sem licença do juiz.","encerrado o debate ou oferecidas as razões finais, o juiz proferirá sentença de imediato ou, excepcionalmente, se complexas as questões, no prazo de 15 dias."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789028","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789028","year":2019,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1071915","sourceQuestionId":"1071915","t":"cpc-m11","moduleId":"cpc-m11","q":"Na audiência de instrução e julgamento, o juiz","o":["exerce o poder de polícia, incumbindo-lhe ordenar que se retirem da sala de audiência quaisquer pessoas que se comportarem inconvenientemente.","só deverá tentar conciliar as partes se não tiver havido prévia audiência de conciliação, ou se alguma delas informar, por ocasião da abertura dos trabalhos, que pretende formular proposta de acordo.","somente poderá proferir sentença se todas as partes e o Ministério Público, nos feitos dos quais participar, concordarem em apresentar suas alegações finais oralmente ou dispensarem a sua apresentação.","não poderá obstar os advogados ou o Ministério Público de intervir ou apartear enquanto depuserem as testemunhas, ainda que sem a sua licença.","poderá, independentemente da concordância das partes, cindir a produção da prova oral, tomando o depoimento das testemunhas presentes e designando outra data para a oitiva das ausentes."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019 • TEC 1071915","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1071915","year":2019,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-732966","sourceQuestionId":"732966","t":"cpc-m11","moduleId":"cpc-m11","q":"Na audiência de instrução e julgamento serão produzidas as provas orais, ouvindo-se","o":["preferencialmente nesta ordem: o perito e os assistentes técnicos; o autor e o réu; e as testemunhas arroladas pelo autor e pelo réu.","obrigatoriamente nesta ordem: o perito e os assistentes técnicos; o autor e o réu; e as testemunhas arroladas pelo autor e pelo réu.","preferencialmente nesta ordem: o autor e o réu; as testemunhas arroladas pelo autor e pelo réu; e o perito e os assistentes técnicos.","obrigatoriamente nesta ordem: o autor e o réu; as testemunhas arroladas pelo autor e pelo réu; e o perito e os assistentes técnicos.","obrigatoriamente nesta ordem: o autor e o réu; o perito e os assistentes técnicos; e as testemunhas arroladas pelo autor e pelo réu."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2018 • TEC 732966","source":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2018","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/732966","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-733918","sourceQuestionId":"733918","t":"cpc-m11","moduleId":"cpc-m11","q":"Acerca da audiência de instrução e julgamento, considere: I. A audiência poderá ser adiada por mera convenção das partes. II. O juiz poderá dispensar a produção das provas requeridas pela parte cujo advogado ou defensor público não tenha comparecido à audiência, aplicando-se a mesma regra ao Ministério Público. III. A audiência é una e contínua, não se admitindo sua cisão em nenhuma hipótese. IV. Mesmo enquanto depuserem as testemunhas, o membro do Ministério Público poderá livremente intervir ou apartear, independentemente de licença do juiz. V. A audiência será pública, inclusive nos feitos que tramitam em segredo de justiça. É correto o que se afirma APENAS em:","o":["I e II.","IV e V.","II e IV.","III e V.","I e III."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE PE)/MPE PE/Administrativa/2018 • TEC 733918","source":"FCC - Tec Min (MPE PE)/MPE PE/Administrativa/2018","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/733918","year":2018,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337735","sourceQuestionId":"337735","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, na audiência de instrução","o":["o Juiz poderá dispensar a produção das provas requeridas pela parte cujo advogado tiver se ausentado injustificadamente.","o Juiz não pode tentar nova conciliação entre as partes.","o perito responderá a qualquer pergunta formulada pelas partes, seja qual for o objeto do questionamento, independentemente da elaboração prévia de quesitos de esclarecimentos.","as testemunhas do juízo são inquiridas sempre depois das do réu.","finda a instrução, o Juiz abrirá prazo para apresentação de alegações-finais, a serem apresentadas necessariamente na forma escrita."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2016 • TEC 337735","source":"FCC - AJ TRT23/TRT 23/Judiciária/Oficial de Justiça Avaliador Federal/2016","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337735","year":2016,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-362384","sourceQuestionId":"362384","t":"cpc-m11","moduleId":"cpc-m11","q":"Em relação à audiência de instrução e julgamento, é correto afirmar:","o":["Enquanto depuserem o perito, os assistentes técnicos, as partes e as testemunhas, não poderão os advogados e o Ministério Público intervir ou apartear, sem licença do juiz.","O juiz poderá dispensar a produção das provas requeridas pela parte cujo advogado ou defensor público não tenha comparecido à audiência, regra porém não aplicável ao Ministério Público, em face dos interesses indisponíveis defendidos.","A audiência é una e contínua, podendo ser excepcionalmente adiada mas em caso algum cindida, ainda que haja concordância das partes.","Quando a causa apresentar questões complexas de fato ou de direito, o debate oral deverá ser substituído por alegações finais, apresentadas sucessivamente pelo autor, réu e Ministério Público, no prazo de dez dias, para cada um, assegurada vista dos autos.","A audiência poderá ser integralmente gravada em imagem ou em áudio, em meio digital ou analógico, inclusive diretamente por qualquer das partes, nesse caso desde que haja autorização judicial."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Pref Campinas)/Pref Campinas/2016 • TEC 362384","source":"FCC - Proc (Pref Campinas)/Pref Campinas/2016","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/362384","year":2016,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-212433","sourceQuestionId":"212433","t":"cpc-m11","moduleId":"cpc-m11","q":"Em uma ação cível, produzida a prova pericial, o réu solicitou esclarecimentos em audiência por parte do perito e do assistente técnico do autor. Somente o autor arrolou testemunhas, tendo o réu requerido o depoimento pessoal do autor. Na audiência de instrução e julgamento, as testemunhas arroladas pelo autor serão ouvidas, obedecida a ordem legal prevista no Código de Processo Civil, após","o":["os esclarecimentos do perito antes do depoimento pessoal do autor e dos esclarecimentos do assistente técnico.","o depoimento pessoal do autor e antes dos esclarecimentos do perito e do assistente técnico.","o depoimento pessoal do autor e os esclarecimentos do perito e do assistente técnico.","os esclarecimentos do perito e do assistente técnico e antes do depoimento pessoal do autor.","os esclarecimentos do perito e do assistente técnico e o depoimento pessoal do autor."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2014 • TEC 212433","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2014","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/212433","year":2014,"caderno":3,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3883940","sourceQuestionId":"3883940","t":"cpc-m12","moduleId":"cpc-m12","q":"Em uma ação individual de indenização por danos morais e estéticos movida pela Defensoria Pública contra uma grande mineradora em razão de desastre ambiental em Mato Grosso, o Defensor Público alega que o assistido (ribeirinho) não possui condição técnica e financeira de produzir prova pericial complexa sobre o nexo de causalidade entre os resíduos encontrados no rio e as enfermidades desenvolvidas. Ao sanear o processo, o juiz decide aplicar a distribuição dinâmica do ônus da prova. Sobre essa decisão, aplicando-se as normas do CPC,","o":["a inversão do ônus da prova por convenção das partes é admitida pelo CPC apenas quando não houver participação da Defensoria Pública no feito.","a distribuição dinâmica do ônus da prova é vedada em ações que envolvam responsabilidade civil ambiental, devendo o autor provar o fato constitutivo e o réu o fato impeditivo em todos os casos.","caso o juiz inverta o ônus da prova na própria sentença, sem aviso prévio, a decisão será válida em razão do princípio do livre convencimento motivado.","a mineradora, ao receber o novo encargo probatório, fica obrigada a arcar antecipadamente com os honorários do perito judicial, sob pena de confissão ficta quanto aos fatos alegados.","o magistrado pode atribuir o ônus da prova de modo diverso quando verificar a excessiva dificuldade de cumprir o encargo ou a maior facilidade de obtenção da prova pela parte contrária, devendo fazê-lo em decisão fundamentada e conceder à parte o direito de se desincumbir do ônus que lhe foi atribuído."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883940","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883940","year":2026,"caderno":3,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937740","sourceQuestionId":"3937740","t":"cpc-m12","moduleId":"cpc-m12","q":"Márcio ajuizou ação de modificação de guarda em face de Joana, maior e capaz. Na petição inicial, o autor informou que a ré não fornecia os cuidados devidos ao filho de 10 anos e, por isso, a guarda fixada anteriormente em favor da mãe deveria ser modificada para que o pai passasse a exercê-la unilateralmente. Joana foi pessoalmente citada, mas não contestou a ação dentro do prazo legal. Nessa situação, de acordo com o Código de Processo Civil,","o":["a autoridade judicial ordenará, de ofício, as provas a serem produzidas, não havendo necessidade de intimação do Ministério Público e/ou da Defensoria Pública.","presumir-se-ão verdadeiras as alegações de fato formuladas por Márcio, devendo a autoridade judicial proceder ao julgamento antecipado do mérito.","a autoridade judicial abrirá prazo para que o autor especifique as provas que pretende produzir, bem como intimará o Ministério Público a se manifestar como fiscal da ordem jurídica.","a Defensoria Pública deverá ser intimada para atuar como curadora especial de Joana, enquanto esta permanecer revel nos autos.","Joana poderá intervir posteriormente no processo, desde que o faça antes da prolação da sentença."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937740","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937740","year":2026,"caderno":3,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488265","sourceQuestionId":"2488265","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, as provas","o":["devem ser produzidas inclusive em relação a fatos notórios e confessados.","podem ser determinadas de ofício.","destinam-se à parte, não podendo o juiz valorá-la em favor da parte que não as requereu.","são apreciadas de acordo com o sistema tarifado.","não podem ser emprestadas de outro processo,"],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488265","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488265","year":2025,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3023464","sourceQuestionId":"3023464","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, as provas","o":["caberão sempre ao autor, quanto ao fato constitutivo de seu direito, não podendo o juiz atribuir o ônus de maneira diversa.","podem ser produzidas pelo réu revel, desde que este se faça representar nos autos a tempo de praticar os atos processuais indispensáveis a essa produção.","não podem ser dispensadas pelo juiz, ainda que recaiam sobre fatos notórios ou admitidos como incontroversos.","não podem ser determinadas de ofício.","só podem ser utilizadas em favor da parte que houver requerido sua produção."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024 • TEC 3023464","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3023464","year":2024,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2340292","sourceQuestionId":"2340292","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a distribuição do ônus da prova","o":["pode ser modificada a critério exclusivo da parte hipossuficiente.","pode ser modificada pelas partes, desde que plenamente capazes, ainda que torne excessivamente difícil a uma delas o exercício do direito.","só pode ser modificada pelas partes se recair sobre direito disponível.","nunca pode ser modificada por convenção das partes, por constituir matéria de ordem pública.","pode ser modificada pelas partes por convenção feita antes do processo, mas não durante ele."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT18/TRT 18/Judiciária/\"Sem Especialidade\"/2023 • TEC 2340292","source":"FCC - AJ TRT18/TRT 18/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2340292","year":2023,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2849463","sourceQuestionId":"2849463","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a distribuição do ônus da prova","o":["pode ser objeto de convenção das partes, desde que celebrada antes do processo.","constitui matéria de ordem pública, não podendo ser objeto de convenção das partes em nenhuma hipótese.","constitui matéria de ordem pública, podendo ser objeto de convenção das partes apenas nas ações sem conteúdo patrimonial expressamente previstas em lei.","pode ser objeto de convenção das partes, salvo quando tornar excessivamente dificil a uma parte o exercício do direito, ou recair sobre direito indisponível da parte.","pode ser objeto de convenção das partes em quaisquer hipóteses, salvo apenas nas ações envolvendo incapazes."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2023 • TEC 2849463","source":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2849463","year":2023,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2850458","sourceQuestionId":"2850458","t":"cpc-m12","moduleId":"cpc-m12","q":"Acerca das provas, considere: I. As provas não podem ser determinadas de ofício, pelo juiz. II. O juiz poderá admitir a prova emprestada, atribuindo-lhe o valor que considerar adequado, observado o contraditório. III. Não dependem de prova os fatos em cujo favor milita presunção legal de existência ou de veracidade. IV. O ônus da prova incumbe ao autor, quanto ao fato constitutivo de seu direito, e ao réu, quanto à existência de fato impeditivo, modificativo ou extintivo do direito do autor, não podendo o juiz distribuir o ônus de modo diverso. De acordo com o Código de Processo Civil, é correto o que se afirma APENAS em","o":["II e IV","I, II e III","I e IV","I e III","II e III"],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023 • TEC 2850458","source":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2850458","year":2023,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1981219","sourceQuestionId":"1981219","t":"cpc-m12","moduleId":"cpc-m12","q":"No Direito Processual Civil brasileiro em vigor, a prova emprestada","o":["permite utilizar da prova produzida em outro feito, em observância da economia processual e da eficiência na prestação jurisdicional, desde que observado o contraditório.","é vedada, uma vez que a utilização de prova produzida em outro feito ofende o princípio da imediatidade e a garantia constitucional do juiz natural.","é permitida apenas em situações de impossibilidade de repetição da prova produzida anteriormente em outro feito.","é admitida, desde que lhe seja atribuído o mesmo valor probatório do processo originário.","somente pode ser admitida pelo juiz em relação a provas produzidas anteriormente em outros feitos em que figurem partes idênticas àquelas envolvidas na demanda na qual se pretende emprestar a prova."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2022 • TEC 1981219","source":"FCC - DP PB/DPE PB/2022","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1981219","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2073351","sourceQuestionId":"2073351","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação à prova e respectivo ônus, considere: I. Cabe ao juiz, a requerimento da parte, somente, já que a jurisdição a ela se dirige, determinar as provas necessárias ao julgamento do mérito, indeferindo em decisão fundamentada as diligências inúteis ou meramente procrastinatórias. II. Incumbe ao terceiro, em relação a qualquer causa, informar ao juiz os fatos e as circunstâncias de que tenha conhecimento, bem como exibir coisa ou documento que esteja em seu poder. III. É admissível a utilização de prova emprestada, atribuindo-lhe o juiz o valor que considerar adequado, observado o contraditório. IV. Não dependem de prova os fatos notórios, os afirmados por uma parte e confessados pela contrária, os admitidos no processo como controversos e em cujo favor milita presunção legal de existência ou de veracidade. Está correto o que se afirma APENAS em","o":["II e III.","I, II e IV.","I e III.","II e IV.","III e IV."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Teresina)/Pref Teresina/2022 • TEC 2073351","source":"FCC - Proc (Teresina)/Pref Teresina/2022","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2073351","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1896281","sourceQuestionId":"1896281","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a prova produzida em outro processo","o":["não é admissível, ainda que as partes dos processos sejam as mesmas.","pode ser admitida, observado o contraditório, atribuindo-lhe o juiz o valor que considerar adequado.","é admissível apenas se irrepetível.","deve receber, do juiz, o mesmo valor que lhe foi atribuído no processo em que produzida, se as partes forem as mesmas.","deve receber, do juiz, o mesmo valor que lhe foi atribuído no processo em que produzida, independentemente de as partes serem as mesmas."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc A (MANAUSPREV)/MANAUSPREV/2021 • TEC 1896281","source":"FCC - Proc A (MANAUSPREV)/MANAUSPREV/2021","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1896281","year":2021,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-789026","sourceQuestionId":"789026","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação às provas, o juiz","o":["apreciará a prova constante dos autos, na dependência do sujeito que a tiver promovido, sua idade e condição social, cultural e econômica, indicando na decisão as razões da formação de seu convencimento.","indeferirá, em decisão que prescinde de fundamentação, as diligências inúteis ou meramente protelatórias.","deverá admitir a utilização da prova produzida em outro processo, atribuindo-lhe necessariamente o mesmo valor considerado no processo em que obtida a prova.","aplicará as regras de experiência comum subministradas pela observação do que ordinariamente acontece e, ainda, as regras de experiência técnica, ressalvado, quanto a estas, o exame pericial.","distribuirá livremente o ônus da prova, utilizando-se de sua discricionariedade, sem ressalvas legais."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789026","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789026","year":2019,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1009452","sourceQuestionId":"1009452","t":"cpc-m12","moduleId":"cpc-m12","q":"Quanto às provas, é correto afirmar:","o":["Na atual sistemática processual civil, não há mais fatos em cujo favor milite presunção legal de existência ou de veracidade para efeito probatório.","Os fatos admitidos no processo como incontroversos dependem apenas de prova oral em audiência que os ratifique.","O juiz aplicará as regras de experiência comum subministradas pela observação do que ordinariamente acontece e, ainda, as regras de experiência técnica, ressalvado, quanto a estas, o exame pericial.","Caberá ao juiz determinar as provas necessárias ao julgamento do mérito, somente se requeridas pela parte, em obediência ao princípio dispositivo.","A existência de algum fato pode ser atestada ou documentada, a requerimento do interessado, mediante ata lavrada por tabelião; excluem-se da ata notarial dados representados por imagem ou som gravados em arquivos eletrônicos."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - OJ (TJ MA)/TJ MA/2019 • TEC 1009452","source":"FCC - OJ (TJ MA)/TJ MA/2019","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1009452","year":2019,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1014418","sourceQuestionId":"1014418","t":"cpc-m12","moduleId":"cpc-m12","q":"O Código de Processo Civil estabelece que, em regra, compete ao autor o ônus da prova quanto aos fatos constitutivos do seu direito, e ao réu, por outro lado, quanto à existência de fato impeditivo, modificativo ou extintivo do direito do autor. Entretanto, o ônus da prova poderá ser distribuído de modo diverso por","o":["convenção das partes, desde que celebrada posteriormente ao ajuizamento da ação.","convenção das partes, desde que celebrada anteriormente ao ajuizamento da ação.","convenção das partes, celebrada antes ou durante o processo.","decisão do juiz, mas não por convenção das partes.","convenção das partes, mas não por decisão do juiz."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - CL (CM Fortal)/CM Fortaleza/Advogado/2019 • TEC 1014418","source":"FCC - CL (CM Fortal)/CM Fortaleza/Advogado/2019","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1014418","year":2019,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-618049","sourceQuestionId":"618049","t":"cpc-m12","moduleId":"cpc-m12","q":"Considere as afirmações a seguir, que concernem à produção das provas processuais. I. Os fatos afirmados por uma parte e confessados pela parte contrária, bem como os notórios, necessitam ser provados nos autos. II. O juiz poderá admitir a utilização de prova produzida em outro processo, atribuindo-lhe o valor que considerar adequado, observado o contraditório. III. Caberá ao juiz, de ofício ou a requerimento da parte, determinar as provas necessárias ao julgamento do mérito, indeferindo, em decisão fundamentada, as diligências inúteis ou meramente protelatórias. IV. As partes têm o direito de empregar todos os meios legais, bem como os moralmente legítimos, desde que especificados na norma processual civil, para provar a verdade dos fatos em que se funda o pedido e influir eficazmente na convicção do juiz. V. A distribuição do ônus da prova pode ocorrer de forma diversa pela vontade das partes, desde que a convenção respectiva seja celebrada durante o curso do processo, necessariamente. Está correto o que se afirma APENAS em","o":["III, IV e V.","I, II e V.","II, III e V.","II e III.","I e IV."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/\"Sem Especialidade\"/2018 • TEC 618049","source":"FCC - AJ TRT6/TRT 6/Judiciária/\"Sem Especialidade\"/2018","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/618049","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-638416","sourceQuestionId":"638416","t":"cpc-m12","moduleId":"cpc-m12","q":"Quanto às provas e seu ônus, considere: I. É defesa a utilização da chamada “prova emprestada” na atual sistemática processual civil. II. No atual código processual civil, o juiz poderá atribuir o ônus da prova de modo diverso ao previsto como regra normativa, desde que o faça por decisão fundamentada, caso em que deverá dar à parte a oportunidade de se desincumbir do ônus que lhe foi atribuído. III. A distribuição diversa do ônus da prova pode ocorrer também por convenção das partes, salvo quando recair sobre direito indisponível da parte ou se tornar excessivamente difícil a uma parte o exercício do direito. IV. Prescindem de prova os fatos notórios, afirmados por uma parte e confessados pela parte contrária, admitidos no processo como incontroversos e em cujo favor milita presunção legal de existência ou de veracidade. V. Caberá ao juiz, somente a requerimento da parte, em razão dos princípios dispositivos e da inércia jurisdicional, determinar as provas necessárias ao julgamento do mérito. Está correto o que se afirma APENAS em","o":["II, III e IV.","I, II e III.","I, II, IV e V.","III e V.","I, IV e V."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Leg (ALESE)/ALESE/Técnico Jurídica/Apoio Jurídico/2018 • TEC 638416","source":"FCC - Ana Leg (ALESE)/ALESE/Técnico Jurídica/Apoio Jurídico/2018","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/638416","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-638725","sourceQuestionId":"638725","t":"cpc-m12","moduleId":"cpc-m12","q":"Quanto às provas, a legislação competente sobre a matéria estabelece:","o":["Se não forem notórios, dependem de prova os fatos afirmados por uma parte e confessados pela parte contrária.","As únicas provas que se admitem nos processos judiciais são as previstas expressamente em lei.","Não pode ser admitida a prova produzida em outro processo por ferir o contraditório e a ampla defesa.","O ônus da prova é sempre o estabelecido na lei processual, não se podendo convencioná-lo de outro modo por acordo das partes.","Caberá ao juiz, de ofício ou a requerimento da parte, determinar as provas necessárias ao julgamento do mérito, indeferindo em decisão fundamentada as diligências inúteis ou meramente protelatórias."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Leg (ALESE)/ALESE/Apoio Técnico ao Processo Legislativo/Processo Legislativo/2018 • TEC 638725","source":"FCC - Ana Leg (ALESE)/ALESE/Apoio Técnico ao Processo Legislativo/Processo Legislativo/2018","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/638725","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-660200","sourceQuestionId":"660200","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação ao Capítulo das Provas no Código de Processo Civil, considere as seguintes afirmações. I. A parte que alegar direito municipal, estadual, estrangeiro ou consuetudinário provar-lhe-á, de imediato, o teor e a vigência. II. A distribuição diversa do ônus da prova pode ocorrer por convenção das partes, antes ou durante o processo. III. Os fatos notórios dependem de prova, quando controvertidos por alguma das partes. IV. Caberá ao juiz, mediante requerimento da parte, determinar as provas necessárias ao julgamento do mérito. Está correto o que consta APENAS de:","o":["I e II.","I e III.","II.","II e IV.","III e IV."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2018 • TEC 660200","source":"FCC - DP RS/DPE RS/2018","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/660200","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-677644","sourceQuestionId":"677644","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação às provas,","o":["as provas no sistema processual civil pátrio obedecem a uma hierarquia de valores, tendo a confissão como a de maior valor e a prova testemunhal como a de menor valor.","caberá ao juiz, desde que requerido pelas partes, determinar as provas necessárias ao julgamento do mérito, indeferindo por despacho as diligências inúteis ou procrastinatórias.","a distribuição diversa do ônus da prova é possível, por acordo das partes, desde que tenha ocorrido durante o processo e não torne excessivamente difícil a uma parte o exercício do direito.","preservado o direito de não propor prova contra si própria, incumbe à parte comparecer em juízo, respondendo ao que lhe for perguntado; colaborar com o juízo na realização de inspeção judicial que for considerada necessária; e praticar o ato que lhe for determinado.","a produção antecipada da prova, na qual não se julga o mérito da causa, previne a competência do juízo para a ação que venha a ser proposta."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE AP)/PGE AP/2018 • TEC 677644","source":"FCC - Proc (PGE AP)/PGE AP/2018","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/677644","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-719789","sourceQuestionId":"719789","t":"cpc-m12","moduleId":"cpc-m12","q":"O ônus da prova é","o":["o encargo que se atribui a um sujeito para demonstração de determinadas alegações de fato; pode ser atribuído pelo legislador, pelo juiz ou pela convenção das partes, não se tratando de um dever e, portanto, não se podendo exigir seu cumprimento.","o encargo atribuído pela lei ou pela convenção das partes para que uma delas demonstre certos fatos, equiparando-se ao dever e, portanto, exigindo-se seu cumprimento.","o dever atribuído à parte para prova de seu direito, disponível sob certas condições subjetivas ou objetivas.","o encargo, que não se confunde com dever, para prova do direito e de certos fatos; é indisponível como regra, não se podendo alterar a distribuição legal dirigida à parte na produção do fato constitutivo do direito.","a regra que determina a autor e réu a produção das provas, de modo estático e inalterável, por se tratar de normatividade cogente."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018 • TEC 719789","source":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/719789","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-719792","sourceQuestionId":"719792","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação à prova, considere: I. Somente os fatos jurídicos, os fatos simples e os fatos positivos podem ser objeto da prova, não podendo sê-lo os fatos negativos. II. Quanto à forma, isto é, modalidade ou maneira pela qual se apresentam em juízo, as provas podem ser orais, documentais ou materiais. III. O juiz poderá admitir a utilização de prova produzida em outro processo, atribuindo-lhe o valor que considerar adequado, observado o contraditório; a isso denomina-se prova emprestada. IV. Caberá ao juiz, de ofício ou a requerimento da parte, determinar as provas necessárias ao julgamento do mérito, indeferindo, em decisão fundamentada, as diligências inúteis ou meramente protelatórias. Está correto o que se afirma APENAS em","o":["II, III e IV.","I e IV.","II e IV.","I e III.","I, II e III."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018 • TEC 719792","source":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/719792","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-467302","sourceQuestionId":"467302","t":"cpc-m12","moduleId":"cpc-m12","q":"O Novo Código de Processo Civil","o":["exige do juiz, sempre que inverter o ônus da prova, que dê oportunidade à parte para se desincumbir do ônus que lhe tenha atribuído.","prevê que a distribuição diversa do ônus da prova também pode ocorrer por convenção das partes, desde que celebrada durante o processo.","extingue a ação cautelar de produção antecipada de provas, não sendo mais possível a dilação probatória em caráter antecedente.","adota com exclusividade a distribuição dinâmica do ônus da prova.","admite a utilização de prova produzida em outro processo, devendo o juiz, contudo, atribuir a ela o mesmo valor dado no processo originário."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PR/DPE PR/2017 • TEC 467302","source":"FCC - DP PR/DPE PR/2017","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/467302","year":2017,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-271879","sourceQuestionId":"271879","t":"cpc-m12","moduleId":"cpc-m12","q":"Mariana fica sabendo que está sendo injuriada e difamada em um site de uma colega de escola, de quem se tornou desafeta por causa de um ex-namorado de ambas. Quer fazer prova contra essa colega, para propor ação indenizatória moral contra ela. Isto, juridicamente, é","o":["impossível, por se tratar de invasão de privacidade ao conteúdo de site alheio, não podendo ser utilizado como prova para fins judiciais, por sua ilicitude.","impossível, pois não há previsão legal de obtenção de prova em sites eletrônicos em nosso processo civil.","possível, desde que o conteúdo do site seja ratificado por prova testemunhal, já que esta se encontra prevista em lei.","possível, pois o sistema de provas brasileiro admite provas tipificadas e não tipificadas em lei, podendo ser extraída uma ata notarial das alegadas injúrias e difamações contra Mariana.","impossível para efeitos civis, pois tratando-se de injúrias e difamações só poderá ser obtida prova para efeitos criminais."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc A (MANAUSPREV)/MANAUSPREV/2015 • TEC 271879","source":"FCC - Proc A (MANAUSPREV)/MANAUSPREV/2015","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/271879","year":2015,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-271987","sourceQuestionId":"271987","t":"cpc-m12","moduleId":"cpc-m12","q":"Escrevendo na vigência do Código de Processo Civil de 1939, Moacyr Amaral Santos afirmou: Não enumera o Código de Processo Civil vigente os meios de prova admissíveis no sistema brasileiro. Seguindo, nesse ponto, o melhor critério limitou a reportar-se aos meios reconhecidos nas leis substantivas (Prova Judiciária no Cível e Comercial − vol. I, pág. 79 − Max Limonad, Editor de Livros de Direito). Essa afirmação","o":["continua válida para o Código de Processo Civil vigente, porque ele traz um rol exemplificativo de meios de prova, que não colide com o do Código Civil.","é parcialmente válida, porque o Código de Processo Civil em vigor não se refere às provas em espécie.","é parcialmente válida, porque o Código Civil em vigor não mais cuida dos meios de prova.","não mais se sustenta perante a legislação processual vigente, porque ela traz um rol taxativo de meios de prova.","sempre foi equivocada, porque, no Brasil, os meios de prova são taxativos."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT6/TRT 6/2015 • TEC 271987","source":"FCC - JT TRT6/TRT 6/2015","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/271987","year":2015,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-251381","sourceQuestionId":"251381","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação ao ônus da prova, é correto afirmar:","o":["É nula a convenção que distribui de maneira diversa o ônus da prova quando recair sobre direito indisponível da parte ou quando tornar excessivamente di fícil a uma parte o exercício do direito.","O sistema processual civil pátrio só admite a inversão convencional da prova, mas não a inversão ju dicial ou legal.","O sistema processual civil pátrio só admite a inversão judicial ou legal da prova, mas não a inversão convencional.","Pelo nosso sistema processual civil, as partes têm o dever, a obrigação legal da produção da prova, o autor quanto ao fato constitutivo de seu direito, o réu quanto ao fato desconstitutivo, modificativo ou extintivo do direito do autor.","O ônus probatório incumbe apenas ao autor ou ao réu, não a terceiros que intervenham no processo."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP CE/DPE CE/2014 • TEC 251381","source":"FCC - DP CE/DPE CE/2014","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/251381","year":2014,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2488262","sourceQuestionId":"2488262","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a produção antecipada de provas","o":["tem cabimento apenas se houver fundado receio de que venha a tomar-se impossível ou muito difícil a verificação de certos fatos na pendência da ação.","dispensa, em todo e qualquer caso, a citação.","é de competência do foro do domicílio do autor.","previne a competência do juízo para a ação que venha a ser proposta.","não admite, em regra, defesa ou recurso, salvo contra decisão que indeferir totalmente a produção da prova pleiteada pelo requerente originário."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488262","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Produção Antecipada da Prova (arts. 381 a 383)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488262","year":2025,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2849467","sourceQuestionId":"2849467","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a produção antecipada da prova","o":["admite defesa, mas não recurso, salvo apenas contra a decisão que deferi-la total ou parcialmente.","é da competência, necessariamente, do juízo do foro onde esta deva ser produzida.","não previne a competência do juízo para a ação que venha a ser proposta.","só será admitida nos casos em que haja fundado receio de que venha a tornar-se impossivel ou muito difícil a verificação de certos fatos na pendência da ação.","dispensa a citação, mesmo se existente caráter contencioso, bem como o recolhimento de custas, salvo aquelas estritamente necessárias à produção da prova."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2023 • TEC 2849467","source":"FCC - AJ TRT21/TRT 21/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Produção Antecipada da Prova (arts. 381 a 383)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2849467","year":2023,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-943390","sourceQuestionId":"943390","t":"cpc-m12","moduleId":"cpc-m12","q":"Acerca da produção antecipada de provas, considere: I. A produção antecipada de provas é admitida, entre outras hipóteses, nos casos em que o prévio conhecimento dos fatos possa justificar ou evitar o ajuizamento de ação. II. O juízo estadual tem competência para produção antecipada de prova requerida em face da União se, na localidade, não houver vara federal. III. A produção antecipada de provas previne a competência do juízo para a ação que venha a ser proposta. IV. Ao final do procedimento da produção antecipada de provas, caberá ao juiz se pronunciar sobre a ocorrência ou a inocorrência do fato, mas não sobre as respectivas consequências jurídicas. V. O procedimento da produção antecipada de prova admite defesa sempre que possuir caráter contencioso. Está correto o que consta APENAS de","o":["I e II.","I e III.","II e IV.","III e V.","IV e V."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2019 • TEC 943390","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Da Produção Antecipada da Prova (arts. 381 a 383)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943390","year":2019,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592257","sourceQuestionId":"592257","t":"cpc-m12","moduleId":"cpc-m12","q":"Considere as assertivas abaixo: I. A produção antecipada da prova não previne a competência do juízo para a ação que venha a ser proposta. II. A inversão judicial do ônus da prova é prevista no CPC/2015 como critério de julgamento e, portanto, deve ser aplicada quando da sentença, desde que cientificadas anteriormente as partes. III. Às partes é vedada a prévia convenção de regras de ônus da prova por meio de negócios jurídicos processuais celebrados anteriormente à formação do processo. IV. Os princípios da persuasão racional e da comunhão da prova estão previstos expressamente no atual Código de Processo Civil. V. É mantida como regra geral o ônus da prova do autor aos fatos constitutivos de seu direito, ao passo que ao réu incumbe a prova dos fatos extintivos, modificativos ou impeditivos do direito do autor. Está correto o que se afirma APENAS em","o":["I, IV e V.","IV e V.","II, III e IV.","I e II.","III e V."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2018 • TEC 592257","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Processual Civil - Da Produção Antecipada da Prova (arts. 381 a 383)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592257","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-373318","sourceQuestionId":"373318","t":"cpc-m12","moduleId":"cpc-m12","q":"A existência e o modo de existir de algum fato podem ser atestados ou documentados","o":["por qualquer servidor público, dada a fé pública dos atos por ele praticados.","por simples declaração do interessado, que se presume verdadeira.","somente pelo registro de documento particular em cartório de títulos e documentos.","por tabelião em ata notarial, a requerimento do interessado.","apenas por escritura pública de declaração, lavrada em notas de tabelião."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJPI/TJ PI/2015 • TEC 373318","source":"FCC - JE TJPI/TJ PI/2015","subject":"Direito Processual Civil - Da Ata Notarial (art. 384)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373318","year":2015,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3227470","sourceQuestionId":"3227470","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, o depoimento pessoal","o":["implica o dever de depor sobre todos os fatos que lhe forem perguntados, sem exceção.","pode ser assistido pela parte que ainda não foi ouvida.","prescinde, para aplicação da pena de confesso, de prévia intimação pessoal.","deve ser requerido pela própria parte, para oitiva dela própria, se desejar expor pessoalmente os fatos.","pode ser colhido por meio de videoconferência, inclusive durante a audiência de instrução e julgamento, se a parte residir em comarca diversa daquela onde tramita à processo."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3227470","source":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Do Depoimento Pessoal (arts. 385 a 388)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3227470","year":2024,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2168708","sourceQuestionId":"2168708","t":"cpc-m12","moduleId":"cpc-m12","q":"Em determinada ação ajuizada conjuntamente por André e Bárbara contra Renato, o réu pleiteou o depoimento pessoal de ambos os autores, bem como o dele próprio. Os autores, por sua vez, abdicaram da produção de prova oral. Nesse caso, de acordo com o Código de Processo Civil, o juiz deverá","o":["deferir o pedido do réu para que seja colhido o próprio depoimento pessoal, pois às partes assiste o direito de expor oralmente os fatos em audiência; além disso, em sendo deferido o depoimento pessoal de ambos os autores, André não poderá assistir ao interrogatório de Bárbara, ainda que já tenha deposto.","deferir o pedido do réu para que seja colhido o próprio depoimento pessoal, pois às partes assiste o direito de expor oralmente os fatos em audiência; além disso, em sendo deferido o depoimento pessoal de ambos os autores, André não poderá assistir ao interrogatório de Bárbara, salvo se já tiver deposto.","indeferir o pedido do réu para que seja colhido o próprio depoimento pessoal, sem prejuízo do poder de ordená-lo de ofício, pois cabe à parte requerer o depoimento pessoal apenas da outra parte; além disso, em sendo deferido o depoimento pessoal de ambos os autores, André não poderá assistir ao interrogatório de Bárbara, salvo se já tiver deposto.","indeferir o pedido do réu para que seja colhido o próprio depoimento pessoal, sem prejuízo do poder de ordená-lo de ofício, pois cabe à parte requerer o depoimento pessoal apenas da outra parte; além disso, em sendo deferido o depoimento pessoal de ambos os autores, André não poderá assistir ao interrogatório de Bárbara, ainda que já tenha deposto.","indeferir o pedido do réu para que seja colhido o próprio depoimento pessoal, que não poderá ser ordenado nem mesmo de ofício, pois a colheita do depoimento pessoal de qualquer das partes depende, necessariamente, de requerimento da outra parte; além disso, em sendo deferido o depoimento pessoal de ambos os autores, André não poderá assistir ao interrogatório de Bárbara, ainda que já tenha deposto."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2022 • TEC 2168708","source":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Do Depoimento Pessoal (arts. 385 a 388)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2168708","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-662309","sourceQuestionId":"662309","t":"cpc-m12","moduleId":"cpc-m12","q":"Considere as assertivas abaixo. I. O depoimento pessoal da parte não pode ser determinado de ofício pelo juiz. II. Em ações de estado e de família, a parte não é obrigada a prestar depoimento sobre fatos, ainda que venham a resultar em desonra própria. III. Haverá confissão ficta quando a parte, pessoalmente intimada para prestar depoimento pessoal e advertida da pena de confesso, não comparece em juízo. IV. É vedado a quem ainda não depôs assistir ao interrogatório da outra parte. V. A parte não tem legitimidade para requerer o seu próprio depoimento pessoal. Em consonância com as disposições do Código de Processo Civil, está correto o que se afirma APENAS em","o":["II e IV.","II, III e V.","I, II e V.","III, IV e V.","I, III e IV."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2018 • TEC 662309","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Processual Civil - Do Depoimento Pessoal (arts. 385 a 388)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/662309","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-893760","sourceQuestionId":"893760","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, o depoimento pessoal","o":["pode ser acompanhado pela parte que ainda não depôs.","impõe que a parte responda a todas as perguntas que lhe forem formuladas, sem exceção, seja qual for a natureza da causa.","pode ser requerido pela própria parte que irá depor.","leva à confissão, caso a parte, que possui advogado constituído, não compareça ou se recuse a depor, ainda que não tenha sido intimada pessoalmente.","será respondido na forma verbal, pela parte, podendo o juiz permitir consulta a notas breves, desde que objetivem completar esclarecimentos."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2015 • TEC 893760","source":"FCC - DP MA/DPE MA/2015","subject":"Direito Processual Civil - Do Depoimento Pessoal (arts. 385 a 388)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/893760","year":2015,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2488263","sourceQuestionId":"2488263","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a confissão","o":["pode ocorrer judicial ou extrajudicialmente.","extrajudicial só pode ser realizada por escrito.","é, em regra, divisível.","deve ser sempre espontânea.","vale como tal e gera efeitos ainda que recaia sobre direitos indisponíveis."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488263","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488263","year":2025,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2152368","sourceQuestionId":"2152368","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a confissão judicial","o":["do cônjuge, nas ações que versarem sobre bens imóveis, só valerá se tiver havido também a do outro, independentemente do regime de bens.","não pode ser provocada.","é irrevogável, mas será ineficaz se feita por quem não era capaz de dispor do direito a que se referem os fatos confessados.","faz prova contra os confitentes e prejudica os litisconsortes.","é, em regra, divisível, podendo a parte que a quiser invocar como prova aceitá-la no tópico que a beneficiar e rejeitá-la no que lhe for desfavorável."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022 • TEC 2152368","source":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2152368","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2230492","sourceQuestionId":"2230492","t":"cpc-m12","moduleId":"cpc-m12","q":"Acerca da confissão no Código de Processo Civil, considere os itens a seguir: I. A confissão de um réu prejudica os demais litisconsortes. II. Não vale como confissão a admissão, em juízo, de fatos relativos a direitos indisponíveis. III. A confissão é irrevogável. IV. A confissão deve ser sempre indivisível. Está correto o que se afirma APENAS em","o":["I e III.","II e IV.","III e IV.","II e III.","I e IV."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2022 • TEC 2230492","source":"FCC - DP MT/DPE MT/2022","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2230492","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-943649","sourceQuestionId":"943649","t":"cpc-m12","moduleId":"cpc-m12","q":"André ajuizou ação de cobrança contra Reinaldo e Letícia, demandando o pagamento de alugueres de um imóvel que lhes havia locado, mediante contrato verbal. Em sua contestação, Reinaldo nega a existência de locação, argumentando que o imóvel lhes havia sido cedido em comodato. Por sua vez, na contestação de Letícia, ela admite a existência da locação, sustentando que ela e Reinaldo, seu irmão, deixaram de pagar os alugueres por conta de dificuldades financeiras. Nesse caso, dada a existência do litisconsórcio passivo, a confissão de Letícia quanto à existência da locação","o":["faz prova apenas contra ela, Letícia.","faz prova contra ela, Letícia, e também contra Reinaldo.","faz prova apenas contra Reinaldo.","faz prova contra ela, Letícia, somente se corroborada por outros meios.","não faz prova contra ela, Letícia, nem contra Reinaldo."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF4/TRF 4/Administrativa/\"Sem Especialidade\"/2019 • TEC 943649","source":"FCC - TJ TRF4/TRF 4/Administrativa/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943649","year":2019,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-592921","sourceQuestionId":"592921","t":"cpc-m12","moduleId":"cpc-m12","q":"No que se refere às regras da confissão previstas no CPC, a confissão","o":["é revogável, como regra, por se tratar de ato jurídico unilateral, podendo ainda ser anulada se decorreu de erro de fato, de dolo ou de coação.","judicial só pode ser espontânea, já que a confissão provocada é exclusiva do procedimento extrajudicial.","judicial faz prova contra o confitente, prejudicando os litisconsortes.","extrajudicial, quando feita oralmente, só terá eficácia nos casos em que a lei não exija prova literal.","em juízo vale como admissão de fatos relativos a direitos indisponíveis, se feita por agente maior e capaz."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2018 • TEC 592921","source":"FCC - Proc (PGE TO)/PGE TO/2018","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/592921","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-677637","sourceQuestionId":"677637","t":"cpc-m12","moduleId":"cpc-m12","q":"A confissão","o":["judicial faz prova contra o confitente, podendo beneficiar ou prejudicar o litisconsorte.","se espontânea, só pode ser feita pela própria parte.","é, em regra, indivisível, não podendo a parte que a quiser invocar como prova aceitá-la no tópico que a beneficiar e rejeitá-la no que lhe for desfavorável, porém cindir-se-á quando o confitente a ela aduzir fatos novos, capazes de constituir fundamento de defesa de direito material ou de reconvenção.","de um cônjuge ou companheiro, nas ações que versarem sobre bens imóveis ou direitos reais sobre imóveis alheios, não valerá sem a do outro.","a confissão é irrevogável, mas pode ser tornada ineficaz se decorreu de erro, de fato ou de direito, dolo ou coação."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE AP)/PGE AP/2018 • TEC 677637","source":"FCC - Proc (PGE AP)/PGE AP/2018","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/677637","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-216915","sourceQuestionId":"216915","t":"cpc-m12","moduleId":"cpc-m12","q":"A confissão","o":["se emanar de erro, dolo ou coação, só poderá ser revogada por meio de ação anulatória do negócio jurídico respectivo.","quando desfavorável ao confitente, pode beneficiar ou prejudicar igualmente seus litisconsortes.","só se caracteriza como tal quando espontânea, pois a provocada diz respeito ao interrogatório da parte em juízo.","não supre a exigência da apresentação de instrumento público, para comprovar a existência de negócio jurídico que o exige como de sua substância.","será sempre expressa, inexistindo confissão ficta ou tácita, em razão das graves consequências jurídicas dela advindas."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2014 • TEC 216915","source":"FCC - DP PB/DPE PB/2014","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/216915","year":2014,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2488268","sourceQuestionId":"2488268","t":"cpc-m12","moduleId":"cpc-m12","q":"Acerca da força probante dos documentos, considere: I. Considera-se autêntico o documento quando não houver impugnação da parte contra quem foi produzido. II. O documento público faz prova apenas da sua formação e não dos fatos que o escrivão, o chefe de secretaria, o tabelião ou o servidor declarar que ocorreram em sua presença. III. O documento feito por oficial público incompetente não possui eficácia, ainda que subscrito pelas partes. IV. A escrituração contábil é indivisível, e, se, dos fatos que resultam dos lançamentos, uns são favoráveis ao interesse de seu autor e outros lhe são contrários, ambos serão considerados em conjunto, como unidade. De acordo com o Código de Processo Civil, está correto o que se afirma APENAS em","o":["I e IV.","II e III.","II e IV.","III e IV.","I e II."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488268","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488268","year":2025,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488269","sourceQuestionId":"2488269","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, os livros empresariais provam","o":["contra seu autor, que não pode alegar fatos contrários a seu conteúdo.","somente na liquidação de sociedade.","apenas em favor de seu autor.","contra seu autor, que pode, todavia, demonstrar, por todos os meios permitidos em direito, que os lançamentos não correspondem à verdade dos fatos.","a favor de quaisquer das partes, ainda que não cumpram os requisitos exigidos por lei."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488269","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488269","year":2025,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3375483","sourceQuestionId":"3375483","t":"cpc-m12","moduleId":"cpc-m12","q":"A respeito do regime jurídico aplicável em matéria de provas no Direito Processual Civil, é correto afirmar:","o":["Não havendo sido apresentada impugnação pela parte ré, não se faz exigível a demonstração da autenticidade de fotografias digitais juntadas aos autos pela parte autora como prova das imagens que por elas são reproduzidas.","A inquirição de testemunhas referidas não pode ser ordenada de ofício pelo juiz.","Durante toda a produção da prova testemunhal, as perguntas serão formuladas pelo juízo, evitando que a parte induza a resposta.","O Código de Processo Civil fez a opção no sentido de considerar inadmissíveis as provas atípicas, sendo nulas as decisões que as tomem como fundamento.","A utilização de extratos digitais de bancos de dados privados como prova fica condicionada à conferência, em juízo, dos dados em questão com os originais constantes dos referidos registros, sendo juridicamente irrelevante o fato de constar dos referidos extratos que o emitente atesta, sob as penas da lei, que as informações conferem com o que consta da origem."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2025 • TEC 3375483","source":"FCC - DP RS/DPE RS/2025","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3375483","year":2025,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2032374","sourceQuestionId":"2032374","t":"cpc-m12","moduleId":"cpc-m12","q":"Em ação que tenha por objeto o descumprimento de obrigação contratual, a parte junta aos autos documento com certificação eletrônica de autoria. Nesse caso, o documento","o":["não poderá ser considerado autêntico, por falta de reconhecimento de firma pelo tabelião.","poderá ser considerado autêntico, se a autoria estiver identificada por certificação eletrônica nele contida, realizada nos termos da lei.","não poderá ser considerado autêntico, por falta de previsão expressa no Código de Processo Civil.","somente será considerado autêntico, se não houver impugnação da parte contra quem o documento foi produzido.","somente poderá ser considerado autêntico, se for admitido como tal pelo juiz, ao avaliar a boa-fé e a verossimilhança dos argumentos da parte."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (UNICAMP)/UNICAMP/2022 • TEC 2032374","source":"FCC - Proc (UNICAMP)/UNICAMP/2022","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2032374","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2168706","sourceQuestionId":"2168706","t":"cpc-m12","moduleId":"cpc-m12","q":"Em determinado processo, o réu arguiu a falsidade de documento apresentado pelo autor, ao passo que este impugnou a autenticidade de documento produzido pelo réu. Nesse caso, de acordo com o Código de Processo Civil, o ônus da prova incumbe","o":["ao autor no tocante à arguição de falsidade, e ao réu no tocante à impugnação da autenticidade.","ao autor no tocante à impugnação da autenticidade, e ao réu no tocante à arguição de falsidade.","apenas ao autor, tanto no tocante à arguição de falsidade quanto em relação à impugnação da autenticidade.","apenas ao réu, tanto no tocante à arguição de falsidade quanto em relação à impugnação da autenticidade.","cumulativamente ao autor e ao réu, tanto no tocante à arguição de falsidade quanto em relação à impugnação da autenticidade."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2022 • TEC 2168706","source":"FCC - AJ TRT23/TRT 23/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2168706","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1769041","sourceQuestionId":"1769041","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com as normas previstas no Código de Processo Civil acerca da prova documental:","o":["O documento público faz prova da declaração, mas não dos fatos que o escrivão, o chefe de secretaria, o tabelião ou o servidor declarar que ocorreram em sua presença, os quais deverão ser confirmados por outros meios legais ou moralmente legítimos.","O documento feito por oficial público incompetente ou sem a observância das formalidades legais, ainda que subscrito pelas partes, não tem eficácia probatória alguma.","A nota escrita pelo credor em qualquer parte de documento representativo de obrigação faz prova em benefício do devedor, mesmo que não tenha sido assinada.","A data do documento particular, quando a seu respeito surgir dúvida ou impugnação entre os litigantes, só pode ser provada por outro documento.","A escrituração contábil é divisível, devendo os fatos que resultam dos lançamentos ser considerados de modo individualizado, na parte em que forem desfavoráveis ao interesse do seu autor, ainda que outra parte lhe seja favorável."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2021 • TEC 1769041","source":"FCC - Proc (PGE GO)/PGE GO/2021","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1769041","year":2021,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-719791","sourceQuestionId":"719791","t":"cpc-m12","moduleId":"cpc-m12","q":"Quanto à prova documental, o Código de Processo Civil estabelece:","o":["A data do documento particular, quando a seu respeito surgir dúvida ou impugnação entre os litigantes, provar-se-á apenas pericialmente.","O documento feito por oficial público incompetente ou sem a observância das formalidades legais será sempre ineficaz juridicamente.","A escrituração contábil é indivisível, e, se dos fatos que resultam dos lançamentos, uns são favoráveis ao interesse de seu autor e outros lhe são contrários, ambos serão considerados em conjunto, como unidade.","Quando a lei exigir instrumento público como da substância do ato, somente instrumento particular subscrito por três testemunhas e com firma reconhecida poderá suprir-lhe a falta.","Considera-se autêntico um documento particular somente quando o tabelião reconheceu a firma do signatário e não houver impugnação por terceiros"],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018 • TEC 719791","source":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/719791","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-733336","sourceQuestionId":"733336","t":"cpc-m12","moduleId":"cpc-m12","q":"O novo Código de Processo Civil, vigente no país desde março de 2016, estabelece que","o":["se presumem falsas em relação ao signatário as declarações constantes de documento particular escrito e assinado ou somente assinado.","os dados representados por imagem ou som gravados em arquivos eletrônicos não poderão constar de uma ata notarial.","as reproduções dos documentos particulares, fotográficas ou obtidas por outros processos de repetição, não valem como certidões, mesmo quando o escrivão certificar sua conformidade com o original.","a utilização de documentos eletrônicos no processo convencional independe de sua conversão à forma impressa e da verificação de sua autenticidade.","o documento feito por oficial público incompetente ou sem a observância das formalidades legais, sendo subscrito pelas partes, tem a mesma eficácia probatória do documento particular."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Min (MPE PE)/MPE PE/Documentação/2018 • TEC 733336","source":"FCC - Ana Min (MPE PE)/MPE PE/Documentação/2018","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/733336","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-734348","sourceQuestionId":"734348","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o previsto no Código de Processo Civil quanto à prova documental,","o":["a falsidade documental em nenhuma hipótese poderá ser suscitada fora da contestação ou da réplica.","o documento feito por oficial público incompetente ou sem a observância das formalidades legais, mesmo subscrito pelas partes, não possui nenhuma eficácia probatória.","a data do documento particular, quando a seu respeito surgir dúvida ou impugnação entre os litigantes, só poderá ser provada por testemunhas.","o documento particular admitido expressa ou tacitamente é sempre divisível, podendo a parte que pretende utilizar-se dele aceitar os fatos que lhe são favoráveis e recusar os que são contrários ao seu interesse.","quando a lei exigir instrumento público como da substância do ato, nenhuma outra prova, por mais especial que seja, pode suprir-lhe a falta."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Jur (SEAD AP)/SEAD AP/2018 • TEC 734348","source":"FCC - Ana Jur (SEAD AP)/SEAD AP/2018","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/734348","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-537010","sourceQuestionId":"537010","t":"cpc-m12","moduleId":"cpc-m12","q":"Com relação à prova documental, a legislação processual civil sobre a matéria estabelece:","o":["Nos casos em que a lei exigir documento público como da substância do ato, se a prova legal existir validamente, o juiz poderá admitir outros meios de prova, em atenção ao princípio do livre convencimento motivado.","Quando o documento particular contiver declaração de ciência de determinado fato, incumbirá ao signatário o ônus de provar a veracidade ou não do fato contido no documento.","Caso haja arguição de falsidade de documento juntado com a inicial, independentemente de pedido de declaração de falsidade incidental, será feito o exame pericial pertinente, ainda que o autor concorde em retirar o documento dos autos, no prazo de réplica.","Incumbe ao réu instruir a contestação com os documentos destinados a provar suas alegações e, a critério do juiz, após expressa justificativa do motivo de impedimento de apresentação anterior, avaliar a possibilidade de juntada de documentos em momento posterior.","Quando intimada para se manifestar sobre documento constante dos autos, poderá a parte impugná-lo como meio de prova, o que significa alegar sua falsidade."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT (CSJT)/CSJT/2017 • TEC 537010","source":"FCC - JT (CSJT)/CSJT/2017","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/537010","year":2017,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-542965","sourceQuestionId":"542965","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil (Lei no 13.105/2015),","o":["o documento feito por oficial público incompetente ou sem a observância das formalidades legais, mesmo que subscrito pelas partes, deixa de ter a eficácia probatória do documento particular.","os dados representados por imagem ou som gravados em arquivos eletrônicos não poderão constar de ata notarial.","fazem a mesma prova que os originais os traslados e as certidões extraídas por oficial público de instrumentos ou documentos lançados em suas notas.","não é lícito às partes juntar aos autos documentos novos, quando destinados a fazer prova de fatos ocorridos depois dos articulados ou para contrapô-los aos que foram produzidos nos autos.","as reproduções dos documentos particulares, fotográficas ou obtidas por outros processos de repetição, valem sempre como certidões, dispensando a verificação de sua conformidade com os originais."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana (DPE RS)/DPE RS/Apoio Especializado/Arquivista/2017 • TEC 542965","source":"FCC - Ana (DPE RS)/DPE RS/Apoio Especializado/Arquivista/2017","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/542965","year":2017,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-583666","sourceQuestionId":"583666","t":"cpc-m12","moduleId":"cpc-m12","q":"Acerca da prova documental, considere: I. O documento feito por oficial público incompetente ou sem a observância das formalidades legais, mesmo que subscrito pelas partes, não tem eficácia probatória alguma. II. Considera-se autor do documento particular aquele que, mandando compô-lo, não o firmou porque, conforme a experiência comum, não se costuma assinar, como livros empresariais e assentos domésticos. III. Quando se tratar de impugnação da autenticidade do documento, incumbe o ônus da prova à parte contra a qual ele foi produzido, independentemente de quem o apresentou. IV. A nota escrita pelo credor em qualquer parte de documento representativo de obrigação, ainda que não assinada, faz prova em benefício do devedor. V. A escrituração contábil é divisível, de modo que, se dos fatos que resultam dos lançamentos, uns forem favoráveis ao interesse de seu autor e outros contrários, caberá ao juiz lhe atribuir a força probatória que merecer, segundo o seu livre convencimento. De acordo com o novo Código de Processo Civil, está correto o que se afirma APENAS em","o":["I e II.","I e III.","II e IV.","III e V.","IV e V."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2017 • TEC 583666","source":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2017","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/583666","year":2017,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-394346","sourceQuestionId":"394346","t":"cpc-m12","moduleId":"cpc-m12","q":"A prova por livros empresariais e escrituração contábil, sujeita-se à seguinte regra:","o":["O juiz sempre poderá ordenar, de ofício ou a requerimento da parte, a exibição integral dos livros empresariais e dos documentos do arquivo, militando a recusa a favor da parte a quem aproveita.","Os livros empresariais, ainda que preenchidos os requisitos legais, só fazem prova contra seu autor.","A escrituração contábil é indivisível, e, se dos fatos que resultam dos lançamentos, uns são favoráveis ao interesse de seu autor e outros lhe são contrários, ambos serão considerados em conjunto, como unidade.","Não é lícito aos empresários provar que os lançamentos em seus livros não correspondem à verdade dos fatos.","Somente nos litígios entre sócios o juiz poderá determinar a exibição integral ou parcial dos livros empresariais, sendo que, em outros litígios, a prova deve ser pericial."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MA)/PGE MA/2016 • TEC 394346","source":"FCC - Proc (PGE MA)/PGE MA/2016","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/394346","year":2016,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-373439","sourceQuestionId":"373439","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação ao ônus da prova, considere: I. Não é possível juridicamente convencionar-se o ônus probatório de modo diverso ao distribuído pela Lei Processual Civil. II. Quando se tratar de falsidade de documento, o ônus da prova cabe à parte que a arguir. III. Quando se tratar de contestação da assinatura, o ônus da prova cabe à parte que produziu o documento. Está correto o que consta APENAS em","o":["I.","I e II.","I e III.","II e III.","II."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJPI/TJ PI/2015 • TEC 373439","source":"FCC - JE TJPI/TJ PI/2015","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373439","year":2015,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3853442","sourceQuestionId":"3853442","t":"cpc-m12","moduleId":"cpc-m12","q":"Na produção da prova testemunhal,","o":["a intimação será feita pela via judicial quando a testemunha houver sido arrolada pelo Ministério Público ou pela Defensoria Pública.","se o juiz for arrolado como testemunha deverá, em qualquer caso, e obrigatoriamente, declarar-se impedido.","o juiz inquirirá as testemunhas conjuntamente na mesma sala, iniciando-se as perguntas àquelas arroladas pelo autor e depois às do réu.","as perguntas serão formuladas às testemunhas de maneira indireta, por intermédio da autoridade judiciária.","depois de apresentado o rol nos autos do processo, não é permitido substituir as testemunhas."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026 • TEC 3853442","source":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3853442","year":2026,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126657","sourceQuestionId":"3126657","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação à prova testemunhal, dispõe o Código de Processo Civil que","o":["a inquirição das testemunhas é realizada sempre por intermédio do juiz, que não admitirá perguntas diretas ou que possam induzir a resposta.","a intimação das testemunhas deve ser realizada, via de regra, por carta precatória ou mandado, conforme residam ou não na comarca em que tramita o processo.","a parte pode requerer a substituição imotivada da testemunha, desde que o faça no prazo de 15 dias da decisão saneadora.","o juiz inquirirá primeiro as testemunhas do autor e depois as do réu, não podendo alterar esta ordem, ainda que a pedido ou com a concordância das partes.","o juiz poderá inquirir a testemunha tanto antes quanto depois da inquirição feita pelas partes."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126657","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126657","year":2024,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2390177","sourceQuestionId":"2390177","t":"cpc-m12","moduleId":"cpc-m12","q":"A respeito das disposições do Código de Processo Civil de 2015 (CPC/2015) e do Estatuto da Pessoa com Deficiência (EPD) sobre a admissão da participação de pessoas com deficiência na condição de testemunhas:","o":["Embora o EPD seja lei posterior em relação ao CPC/2015, as disposições deste são mais específicas quanto aos incapazes de testemunhar, de modo que prevalece a previsão de que o interdito por enfermidade ou deficiência mental é impedido de testemunhar, nos termos previstos na lei instrumental.","O CPC/2015 considera como incapazes de testemunhar, dentre outras hipóteses, o interdito por enfermidade ou deficiência mental, mas tal diploma foi revogado tacitamente pela superveniência da entrada em vigor do EPD, que estabelece que a pessoa com deficiência poderá testemunhar em igualdade de condições com as demais pessoas, sendolhe assegurados todos os recursos de tecnologia assistiva.","O CPC/2015 considera como incapazes de testemunhar, dentre outras hipóteses, o interdito por enfermidade ou deficiência mental, mas tal diploma foi revogado expressamente pela superveniência da entrada em vigor do EPD, que estabelece que a pessoa com deficiência poderá testemunhar em igualdade de condições com as demais pessoas, sendolhe assegurados todos os recursos de tecnologia assistiva.","Tanto o CPC/2015 como o EPD asseguram expressamente que a pessoa com deficiência poderá testemunhar em igualdade de condições com as demais pessoas, sendo-lhe assegurados todos os recursos de tecnologia assistiva, não havendo qualquer conflito entre leis em relação ao tema neste particular.","O CPC/2015 considera como incapazes de testemunhar, dentre outras hipóteses, o interdito por enfermidade ou deficiência mental e tal diploma entrou em vigor supervenientemente ao EPD; entretanto tais disposições não revogaram expressamente as diretrizes do Estatuto da Pessoa com Deficiência que asseguram que a pessoa com deficiência poderá testemunhar em igualdade de condições com as demais pessoas, sendo-lhe assegurados todos os recursos de tecnologia assistiva."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SP/DPE SP/2023 • TEC 2390177","source":"FCC - DP SP/DPE SP/2023","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2390177","year":2023,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2212017","sourceQuestionId":"2212017","t":"cpc-m12","moduleId":"cpc-m12","q":"A respeito da prova testemunhal, o Código de Processo Civil em vigor","o":["revogou expressamente dispositivos do Estatuto da Pessoa com Deficiência quanto ao depoimento de pessoas interditadas ou deficientes.","afasta a capacidade de todas as pessoas com enfermidade ou deficiência mental para servir como testemunhas em processos judiciais.","afirma serem incapazes de depor como testemunhas as pessoas impedidas ou suspeitas, de modo que seu relato não pode ser admitido pelo juiz.","atribui capacidade para servir como testemunha aos maiores de dezesseis anos de idade, não se confundindo a capacidade para ser testemunha com a capacidade civil.","não admite a prova exclusivamente testemunhal para a prova dos vícios de consentimento nos contratos em geral."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP (DPE AP)/DPE AP/2022 • TEC 2212017","source":"FCC - DP (DPE AP)/DPE AP/2022","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2212017","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1752318","sourceQuestionId":"1752318","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com a sistemática civil e processual civil em vigor, a prova testemunhal pode ser utilizada como base exclusiva para","o":["o reconhecimento de obrigações para as quais a lei exija a forma escrita, em qualquer circunstância, em razão do princípio da persuasão racional.","o reconhecimento de obrigações contraídas verbalmente, ainda que o valor seja superior a dez salários-mínimos.","o esclarecimento de questões que dependam de um conhecimento técnico ou científico.","o reconhecimento de atos jurídicos para os quais a lei exige instrumento público, desde que haja início de prova escrita.","sustentar a existência de direito líquido e certo em sede de mandado de segurança."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP GO/DPE GO/2021 • TEC 1752318","source":"FCC - DP GO/DPE GO/2021","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1752318","year":2021,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1896340","sourceQuestionId":"1896340","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, na audiência de instrução e julgamento,","o":["o juiz, ao término da instrução, abrirá prazo para apresentação de alegações finais, em regra escritas, admitindo-se debates orais apenas se todas as partes concordarem.","o perito é ouvido preferencialmente por último, depois das partes e das testemunhas.","o juiz poderá inquirir a testemunha tanto antes quanto depois da inquirição feita pelas partes.","a parte, até o final do depoimento da testemunha, poderá apresentar contradita, que, se acolhida, imporá sua oitiva na qualidade de informante.","aplica-se a pena de confesso independentemente de intimação da parte para prestar depoimento pessoal ou de adver tência específica."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc A (MANAUSPREV)/MANAUSPREV/2021 • TEC 1896340","source":"FCC - Proc A (MANAUSPREV)/MANAUSPREV/2021","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1896340","year":2021,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-537013","sourceQuestionId":"537013","t":"cpc-m12","moduleId":"cpc-m12","q":"Com relação à prova testemunhal, a legislação processual civil sobre a matéria estabelece:","o":["É inadmissível sobre fato objeto de documento impugnado pela parte adversa àquela que o apresentou nos autos, bem como sobre fato provado por confissão da parte que afaste vício formal do documento.","Os condenados por falso testemunho, assim considerados indignos de fé, são considerados suspeitos para depor como testemunha, por expressa disposição legal.","O respeito à intimidade da testemunha prepondera sobre o dever de dizer a verdade no processo, quando os fatos acarretarem grave dano à testemunha ou sobre os quais deva guardar sigilo, por estado ou profissão.","O juiz da causa arrolado como testemunha e que tenha ciência de fatos que possam influir na decisão deverá depor e, em seguida, declarar seu impedimento para prosseguir na instrução e julgamento do feito.","O juiz inquirirá primeiro as testemunhas do autor e depois as testemunha do réu, podendo essa ordem ser alterada pelo juiz de modo justificado, independentemente da concordância de ambas as partes."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT (CSJT)/CSJT/2017 • TEC 537013","source":"FCC - JT (CSJT)/CSJT/2017","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/537013","year":2017,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-539649","sourceQuestionId":"539649","t":"cpc-m12","moduleId":"cpc-m12","q":"Julio, representado por seu advogado contratado Paulo, ajuizou ação indenizatória contra Maria, esta última hipossuficiente representada pela Defensoria Pública. Designada audiência de instrução pelo Magistrado que preside o feito, Julio arrola três testemunhas: Manoel, Manoela e Ricardo, este último o juiz da causa. Já Maria arrola as testemunhas Roberta e Paola. Os autos do processo são eletrônicos. Especificamente sobre a prova testemunhal, de acordo com o Código de Processo Civil,","o":["colhido o depoimento por meio de gravação e havendo recurso o depoimento deverá ser, em regra, digitado, antes da remessa dos autos à segunda instância.","o juiz da causa Ricardo, arrolado como testemunha, deverá declarar-se impedido, ainda que não saiba nada sobre os fatos tratados no processo.","o juiz deverá obrigatoriamente inquirir as testemunhas apresentadas antes da inquirição feita pelas partes.","a testemunha pode requerer ao juiz o pagamento da despesa que efetuou para comparecimento à audiência, pagamento este que será realizado ao final do processo, após o trânsito em julgado, pela parte vencida.","em regra, caberá ao advogado de Julio informar ou intimar as testemunhas Manoel e Manoela acerca do dia, da hora e do local da audiência designada, dispensando-se a intimação do juízo."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana (DPE RS)/DPE RS/Jurídica/Processual/2017 • TEC 539649","source":"FCC - Ana (DPE RS)/DPE RS/Jurídica/Processual/2017","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/539649","year":2017,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-362385","sourceQuestionId":"362385","t":"cpc-m12","moduleId":"cpc-m12","q":"Quanto à produção da prova testemunhal, é correto afirmar:","o":["As perguntas serão formuladas pelas partes diretamente à testemunha, começando pela que a arrolou, não admitindo o juiz aquelas que puderem induzir a resposta, não tiverem relação com as questões de fato objeto da atividade probatória ou importarem repetição de outra já respondida.","A intimação da testemunha só será feita pela via judicial quando ela houver sido arrolada pelo Ministério Público ou pela Defensoria, ou ainda quando se frustrar a intimação por via postal.","Cabe ao Juízo informar ou intimar a testemunha arrolada pela parte do dia, da hora e do local da audiência designada, dispensando-se a intimação postal.","O juiz inquirirá as testemunhas separada e sucessivamente, primeiro as do réu e depois as do autor, e providenciará para que uma não ouça o depoimento das outras; o juiz poderá alterar essa ordem, a seu livre arbítrio.","É lícito à parte contraditar a testemunha, arguindo-lhe a incapacidade, o impedimento ou a suspeição, bem como, caso a testemunha negue os fatos que lhe s ão imputados, provar a contradita, somente com documentos."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Pref Campinas)/Pref Campinas/2016 • TEC 362385","source":"FCC - Proc (Pref Campinas)/Pref Campinas/2016","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/362385","year":2016,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-396151","sourceQuestionId":"396151","t":"cpc-m12","moduleId":"cpc-m12","q":"Sobre a prova testemunhal, é correto afirmar que","o":["esta é inadmissível quando a lei exigir prova escrita da obrigação, ainda que haja começo de prova escrita emanada da parte contra a qual se pretende produzir a prova.","a parte pode se comprometer a levar a testemunha à audiência independentemente de intimação, que, em regra, deve ser realizada por carta com aviso de recebimento.","é defeso à parte, nos contratos simulados, provar com testemunhas a divergência entre a vontade real e a vontade declarada, ou, nos contratos em geral, os vícios de consentimento.","pode o juiz, se necessário, admitir o depoimento de testemunhas menores, impedidas ou suspeitas, devendo tomar-lhes compromisso.","o juiz deve ouvir primeiro as testemunhas do autor e depois as do réu, não podendo inverter a ordem das oitivas ainda que as partes concordem."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2016 • TEC 396151","source":"FCC - DP BA/DPE BA/2016","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/396151","year":2016,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-290356","sourceQuestionId":"290356","t":"cpc-m12","moduleId":"cpc-m12","q":"Quanto à prova testemunhal, no procedimento ordinário, é correto afirmar:","o":["A intimação de testemunha só poderá ser feita por meio de oficial de justiça.","O rol de testemunhas deverá sempre ser apresentado com a petição inicial e com a contestação.","A parte não poderá substituir testemunha que, por enfermidade, não estiver em condições de depor.","Cada uma das partes poderá arrolar, no máximo, dez testemunhas.","A testemunha não pode escusar-se de depor sobre fatos que lhe acarretem grave dano."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2015 • TEC 290356","source":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2015","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/290356","year":2015,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3930557","sourceQuestionId":"3930557","t":"cpc-m12","moduleId":"cpc-m12","q":"Com base nas disposições do Código de Processo Civil, um perito-contador nomeado em um processo judicial, após a ciência de sua nomeação, deve","o":["apresentar, no prazo de 15 dias, resumo geral do trabalho a ser realizado, com as minutas de provas pré-preenchidas.","prestar compromisso formal nos autos para validar o encargo que lhe foi cometido, sob pena de nulidade da perícia realizada.","notificar as partes sobre sua nomeação, que deve ser aceita. Eventual discordância ocorre em sede de recurso processual.","apresentar, em 5 dias, proposta de honorários.","arbitrar os honorários periciais, após a manifestação das partes."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - ALegis (ALMS)/ALMS/Contador/2026 • TEC 3930557","source":"FCC - ALegis (ALMS)/ALMS/Contador/2026","subject":"Direito Processual Civil - Da Prova Pericial (arts. 464 a 480)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3930557","year":2026,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488271","sourceQuestionId":"2488271","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a prova pericial","o":["pode ser realizada pelo próprio juiz que tiver formação acadêmica especifica na área objeto da prova.","pode ser determinada de ofício.","não pode ser dispensada, ainda que as partes, na inicial e na contestação, hajam apresentado, sobre as questões de fato, pareceres técnicos ou documentos elucidativos que considerem suficientes.","será determinada ainda que outras provas sejam suficientes para o julgamento do mérito.","vincula o juiz, que não pode decidir contrariamente ao laudo."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488271","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Prova Pericial (arts. 464 a 480)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488271","year":2025,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2712711","sourceQuestionId":"2712711","t":"cpc-m12","moduleId":"cpc-m12","q":"Segundo o Código de Processo Civil, a prova técnica simplificada","o":["relaciona-se a não complexidade em sua elaboração. sendo menos dispendiosa.","pode substituir a prova pericial, quando a controvérsia for de menor complexidade.","não é admitida no nosso ordenamento jurídico desde a reforma do CPC em 2016.","foi alçada à espécie de prova pericial, classificando-se dentre as de menor complexidade.","não permite o formato de inquirição do especialista, apresentando formato documental."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2023 • TEC 2712711","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2023","subject":"Direito Processual Civil - Da Prova Pericial (arts. 464 a 480)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2712711","year":2023,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-760261","sourceQuestionId":"760261","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação à prova pericial,","o":["somente se requerido pelas partes, o juiz poderá substitui-la pela produção de prova técnica simplificada, quando o ponto controvertido for de menor complexidade.","o perito cumprirá escrupulosamente o encargo que lhe foi cometido, firmando um termo de compromisso nos autos, obrigatoriamente, por se tratar de auxiliar do Judiciário.","o impedimento ou a suspeição do perito, conforme o caso, devem ser arguidos em até quinze dias após a apresentação do laudo técnico, sob pena de preclusão.","o juiz poderá dispensá-la quando as partes, na inicial e na contestação, apresentarem, sobre as questões de fato, pareceres técnicos ou documentos elucidativos que considerar suficiente.","se houver necessidade de segunda perícia, esta substitui a primeira, cabendo ao juiz desconsiderá-la e apreciar o valor da segunda."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Mun (Caruaru)/Pref Caruaru/2018 • TEC 760261","source":"FCC - Proc Mun (Caruaru)/Pref Caruaru/2018","subject":"Direito Processual Civil - Da Prova Pericial (arts. 464 a 480)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/760261","year":2018,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-438208","sourceQuestionId":"438208","t":"cpc-m12","moduleId":"cpc-m12","q":"Considere as proposições abaixo, acerca da prova pericial. I. O perito não está sujeito às causas de suspeição e impedimento, por não ser parte no processo. II. O juiz poderá autorizar o pagamento da integralidade dos honorários antes do início dos trabalhos. III. Os assistentes técnicos não estão sujeitos a impedimento ou suspeição. IV. O juiz poderá dispensar prova pericial quando as partes, na inicial e na contestação, apresentarem, sobre as questões de fato, pareceres técnicos ou documentos elucidativos que considerar suficientes. Está correto o que se afirma APENAS em","o":["II e III.","I e II.","III e IV.","I e IV.","I."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2016 • TEC 438208","source":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2016","subject":"Direito Processual Civil - Da Prova Pericial (arts. 464 a 480)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/438208","year":2016,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-269247","sourceQuestionId":"269247","t":"cpc-m12","moduleId":"cpc-m12","q":"A respeito da prova pericial:","o":["para desempenharem suas funções, podem o perito e os assistentes técnicos ouvir testemunhas e solicitar documentos que estejam em poder das partes.","o perito pode ser substituído se, em outra perícia, houver elaborado laudo acerca do mesmo objeto.","o juiz fica vinculado ao laudo se as partes e os assistentes técnicos não contrariarem suas conclusões.","as partes não podem acompanhar os trabalhos periciais.","a manifestação das partes e assistentes técnicos acerca do laudo se dá, exclusivamente, após a audiência de instrução e julgamento, por ocasião do debate oral ou dos memoriais."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Adv (SABESP)/SABESP/2014 • TEC 269247","source":"FCC - Adv (SABESP)/SABESP/2014","subject":"Direito Processual Civil - Da Prova Pericial (arts. 464 a 480)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/269247","year":2014,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2154181","sourceQuestionId":"2154181","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o disposto no Código de Processo Civil, a inspeção judicial","o":["é ato exclusivo do oficial de justiça, que a realizará com ou sem auxílio de perito, de ofício ou a requerimento das partes.","poderá ser realizada, pelo Juiz, sempre a requerimento das partes e com auxílio de perito.","é ato exclusivo do oficial de justiça, que a realizará sempre com auxílio de perito, de ofício ou a requerimento das partes.","poderá ser realizada, pelo Juiz, de ofício ou a requerimento das partes, com ou sem auxílio de perito.","é ato exclusivo do oficial de justiça, que a realizará com ou sem auxílio de perito e apenas a requerimento das partes."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Of Jus (TJ CE)/TJ CE/2022 • TEC 2154181","source":"FCC - Of Jus (TJ CE)/TJ CE/2022","subject":"Direito Processual Civil - Da Inspeção Judicial (arts. 481 a 484)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2154181","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2975465","sourceQuestionId":"2975465","t":"cpc-m12","moduleId":"cpc-m12","q":"Com relação às provas, considere: I. Cabe à parte requerer o depoimento pessoal da outra parte, a fim de que esta seja interrogada na audiência de instrução e julgamento, sendo vedado ao juiz ordená-lo de ofício. II. Nas ações que versarem sobre bens imóveis ou direitos reais sobre imóveis alheios, a confissão de um cônjuge ou companheiro não valerá sem a do outro, salvo se o regime de casamento for o de separação absoluta de bens. III. O juiz não pode ordenar, em nenhuma hipótese, a requerimento da parte, a exibição integral dos livros empresariais e dos documentos do arquivo na sucessão por morte de sócio. Em conformidade com o Código de Processo Civil, está correto o que se afirma em","o":["II, apenas.","I e III, apenas.","I, II e III.","I, apenas.","III, apenas."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Adv (CETESB)/CETESB/2024 • TEC 2975465","source":"FCC - Adv (CETESB)/CETESB/2024","subject":"Direito Processual Civil - Tópicos Mesclados do Capítulo \"das Provas\"","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2975465","year":2024,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021315","sourceQuestionId":"2021315","t":"cpc-m12","moduleId":"cpc-m12","q":"Analise as proposições abaixo, acerca da prova: I. O Juiz que tiver conhecimentos técnicos poderá dispensar a indicação de perito e conduzir, ele próprio, a prova pericial. II. É vedado ao juiz admitir o depoimento de testemunhas menores, impedidas ou suspeitas. III. A inspeção judicial pode ser determinada de ofício. IV. As partes podem, a qualquer tempo, juntar aos autos documentos novos, quando destinados a fazer prova de fatos ocorridos depois dos articulados ou para contrapô-los aos que foram produzidos nos autos. Está correto o que se afirma APENAS em","o":["II e III.","II e IV.","I e III.","I e II.","III e IV."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Proc (PGE AM)/PGE AM/2022 • TEC 2021315","source":"FCC - Ana Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Tópicos Mesclados do Capítulo \"das Provas\"","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021315","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2038255","sourceQuestionId":"2038255","t":"cpc-m12","moduleId":"cpc-m12","q":"Uma pessoa comparece até a Defensoria Pública do Estado do Ceará almejando a reparação de danos morais em razão de publicações em redes sociais. Apresentou como provas prints das publicações ofensivas que tirou em seu próprio celular em página com conteúdo acessível a todos os usuários daquela rede social. Diante de tal circunstância, o/a defensor/a público/a","o":["não poderia requerer a juntada de tais prints na petição inicial, uma vez que, embora se enquadrem no conceito legal de documento adotado pelo Código de Processo Civil, a produção de prova documental deve ser resguardada para a fase instrutória, não sendo adequada a juntada de documentos desta natureza na exordial.","não poderia requerer a juntada de tais prints na petição inicial, uma vez que não se enquadram no conceito legal de documento adotado pelo Código de Processo Civil, bem como em nenhuma outra espécie de prova admitida por lei, configurando hipótese de prova ilegítima, porquanto violadora de normas processuais.","poderia requerer a juntada de tais prints na petição inicial, porém, é recomendável que adote providências para evitar a invalidação da prova em caso de impugnação e necessidade de eventual perícia, seja por meio da captura técnica com metadados ou por meio de ata notarial.","poderia requerer a juntada de tais prints na petição inicial, mas diante da impugnação ou dúvidas quanto à manipulação do seu conteúdo, o magistrado deverá inadmitir de plano a prova, independentemente da realização de perícia quanto ao conteúdo da publicação.","não poderia requerer a juntada de tais prints na petição inicial, uma vez que a produção de prova desta natureza deve ser feita exclusivamente por meio de ata notarial, hipótese apontada pela doutrina como resquício do sistema da prova tarifada ou legal."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP CE/DPE CE/2022 • TEC 2038255","source":"FCC - DP CE/DPE CE/2022","subject":"Direito Processual Civil - Tópicos Mesclados do Capítulo \"das Provas\"","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2038255","year":2022,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1736854","sourceQuestionId":"1736854","t":"cpc-m12","moduleId":"cpc-m12","q":"Acerca das provas, considere: I. Para que seja aplicada, a pena de confesso demanda prévia intimação pessoal para o depoimento pessoal. II. O juiz não pode indeferir a prova testemunhal ainda que os fatos hajam sido confessados. III. O perito pode escusar-se da nomeação, caso em que o juiz nomeará novo perito. IV. Findo o depoimento, a parte poderá contraditar a testemunha. Está correto o que se afirma APENAS em","o":["II, III e IV.","I e III.","II e IV.","I.","I, II e III."],"a":1,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736854","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Processual Civil - Tópicos Mesclados do Capítulo \"das Provas\"","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736854","year":2021,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-989787","sourceQuestionId":"989787","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação à prova, considere: I. O ônus da prova pode ser atribuído de modo diverso pelo juízo, desde que o faça por decisão fundamentada, e que as peculiaridades da causa reflitam em impossibilidade ou excessiva dificuldade em cumprir o encargo a que se incumbiu a parte, caso em que deverá dar à parte a oportunidade de se desincumbir do ônus que lhe foi atribuído. II. Não é permitido ao juízo proceder à inquirição de especialista sobre ponto controvertido da causa que demande especial conhecimento científico ou técnico, sob pena de violação aos direitos do consumidor. III. O perito pode ser substituído apenas se lhe faltar conhecimento técnico ou científico. IV. Mesmo em razão de enfermidade, a testemunha que estiver impossibilitada de comparecer à audiência, mas não de prestar depoimento, será inquirida na sede do juízo. Está correto o que consta APENAS de","o":["I e II.","II e IV.","III e IV.","I.","II e III."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (SANASA)/SANASA/Jurídico/2019 • TEC 989787","source":"FCC - Proc (SANASA)/SANASA/Jurídico/2019","subject":"Direito Processual Civil - Tópicos Mesclados do Capítulo \"das Provas\"","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/989787","year":2019,"caderno":4,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"});
